CREATE TABLE IF NOT EXISTS regulatory_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, authority_name text NOT NULL, source_title text NOT NULL, source_url text NOT NULL, source_type text NOT NULL, publication_date timestamptz, effective_date timestamptz, retrieved_at timestamptz NOT NULL DEFAULT now(), source_hash text, authority_verified boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Discovered', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS regulatory_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES regulatory_sources(id) ON DELETE CASCADE, rule_code text NOT NULL, rule_domain text NOT NULL, rule_text text NOT NULL, applicability text, effective_from timestamptz, effective_until timestamptz, validation_status text NOT NULL DEFAULT 'Pending', legal_review_status text NOT NULL DEFAULT 'Required', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS regulatory_validation_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid NOT NULL REFERENCES regulatory_rules(id) ON DELETE CASCADE, reviewer_reference text, reviewer_type text NOT NULL, independence_declaration text, decision text NOT NULL DEFAULT 'Pending', rationale text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS regulatory_framework_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, version_label text NOT NULL, status text NOT NULL DEFAULT 'Draft', rule_count integer NOT NULL DEFAULT 0, validated_rule_count integer NOT NULL DEFAULT 0, source_count integer NOT NULL DEFAULT 0, effective_from timestamptz, effective_until timestamptz, release_notes text, activated_by_reference text, activated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_reg_sources_jurisdiction ON regulatory_sources(jurisdiction_id,status);
CREATE INDEX IF NOT EXISTS idx_reg_rules_source ON regulatory_rules(source_id,validation_status,legal_review_status);
CREATE INDEX IF NOT EXISTS idx_reg_reviews_rule ON regulatory_validation_reviews(rule_id,decision);
CREATE INDEX IF NOT EXISTS idx_reg_versions_jurisdiction ON regulatory_framework_versions(jurisdiction_id,status);